-- Initial TEST-only orphan publication headers, not claimed native publication.
-- All reconciliation decisions and subsequent scheduling use actual commands.
begin;set local search_path=public,extensions;select no_plan();
grant usage on schema extensions to authenticated;
insert into auth.users(id,instance_id,aud,role,email,encrypted_password,email_confirmed_at,raw_app_meta_data,raw_user_meta_data,created_at,updated_at)
select('a3790000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'00000000-0000-0000-0000-000000000000','authenticated','authenticated','window379-'||n||'@example.invalid','',now(),'{}','{}',now(),now()from generate_series(1,3)n;
insert into public.platform_user_roles(user_id,role_code)values('a3790000-0000-4000-8000-000000000001','MATRICIA_ADMIN'),('a3790000-0000-4000-8000-000000000002','MATRICIA_ADMIN');
insert into public.organizations(id,legal_name,display_name,status,created_by)values('b3790000-0000-4000-8000-000000000001','TEST379 catalogue','TEST379 catalogue','ACTIVE','a3790000-0000-4000-8000-000000000001');
insert into public.catalog_libraries(id,code,slug,steward_organization_id,created_by)values('c3790000-0000-4000-8000-000000000001','TEST379','test379','b3790000-0000-4000-8000-000000000001','a3790000-0000-4000-8000-000000000001'),('c3790000-0000-4000-8000-000000000002','TEST379_AUDIENCE','test379-audience','b3790000-0000-4000-8000-000000000001','a3790000-0000-4000-8000-000000000001');
insert into public.catalog_releases(id,library_id,release_key,status,source_bundle_hash,snapshot_hash,created_by,published_at,effective_from,audience)
select id,lib,key,'PUBLISHED',repeat(hash,64),repeat(hash,64),'a3790000-0000-4000-8000-000000000001',now()-interval'1 day',starts_at,audience
from(values
 ('d3790000-0000-4000-8000-000000000001'::uuid,'c3790000-0000-4000-8000-000000000001'::uuid,'TEST379.ORPHAN','a',now()-interval'1 day','{"kind":"PUBLIC"}'::jsonb),
 ('d3790000-0000-4000-8000-000000000002'::uuid,'c3790000-0000-4000-8000-000000000001'::uuid,'TEST379.CURRENT','b',now()-interval'2 days','{"kind":"PUBLIC"}'::jsonb),
 ('d3790000-0000-4000-8000-000000000004'::uuid,'c3790000-0000-4000-8000-000000000002'::uuid,'TEST379.DISTINCT.AUDIENCE','d',now()-interval'1 day','{"kind":"ORGANIZATIONS","organization_ids":["b3790000-0000-4000-8000-000000000001"]}'::jsonb),
 ('d3790000-0000-4000-8000-000000000005'::uuid,'c3790000-0000-4000-8000-000000000002'::uuid,'TEST379.OTHER.CURRENT','e',now()-interval'2 days','{"kind":"PUBLIC"}'::jsonb)
)initial(id,lib,key,hash,starts_at,audience);
update public.catalog_libraries set current_release_id=case id when'c3790000-0000-4000-8000-000000000001'then'd3790000-0000-4000-8000-000000000002'::uuid else'd3790000-0000-4000-8000-000000000005'::uuid end where id in('c3790000-0000-4000-8000-000000000001','c3790000-0000-4000-8000-000000000002');
insert into public.catalog_releases(id,library_id,release_key,status,source_bundle_hash,snapshot_hash,created_by,based_on_release_id,approved_by,approved_at)
values('d3790000-0000-4000-8000-000000000003','c3790000-0000-4000-8000-000000000001','TEST379.APPROVED.CANDIDATE','APPROVED',repeat('c',64),repeat('c',64),'a3790000-0000-4000-8000-000000000001','d3790000-0000-4000-8000-000000000002','a3790000-0000-4000-8000-000000000002',now());
-- An actual in-flight publisher must be refused before inverse-order locks.
insert into public.catalog_releases(id,library_id,release_key,status,source_bundle_hash,created_by,lease_token,leased_until)
values('d3790000-0000-4000-8000-000000000006','c3790000-0000-4000-8000-000000000002','TEST379.INFLIGHT','PUBLISHING',repeat('f',64),'a3790000-0000-4000-8000-000000000001','e3790000-0000-4000-8000-000000000006',now()+interval'5 minutes');
create temporary table windows379(k text primary key,v jsonb);grant select,insert on windows379 to authenticated;
insert into windows379 select'target-before',to_jsonb(r)from public.catalog_releases r where id='d3790000-0000-4000-8000-000000000001';
insert into windows379 select'current-before',to_jsonb(r)from public.catalog_releases r where id='d3790000-0000-4000-8000-000000000002';
create function pg_temp.actor379(n integer,aal text default'aal2')returns void language plpgsql as $$begin perform set_config('request.jwt.claim.role','authenticated',true);perform set_config('request.jwt.claim.sub','a3790000-0000-4000-8000-'||lpad(n::text,12,'0'),true);perform set_config('request.jwt.claims',jsonb_build_object('sub','a3790000-0000-4000-8000-'||lpad(n::text,12,'0'),'role','authenticated','aal',aal)::text,true);end$$;
set local role authenticated;select pg_temp.actor379(1);
select throws_ok($$select public.schedule_reviewed_catalog_release('d3790000-0000-4000-8000-000000000003',1,repeat('c',64),clock_timestamp(),null,'TEST379-schedule-blocked')$$,'23P01','CATALOG_SCHEDULE_CONFLICT','the real reviewed scheduler initially rejects the orphan overlapping publication');
select throws_ok($$select public.request_catalog_release_window_closure_v1('d3790000-0000-4000-8000-000000000002',1,repeat('b',64),'TEST current must remain available','TEST379-deny-current')$$,'55000','CATALOG_RELEASE_WINDOW_REVIEW_NOT_ELIGIBLE','a central actor cannot close the current release through reconciliation');
select throws_ok($$select public.request_catalog_release_window_closure_v1('d3790000-0000-4000-8000-000000000004',1,repeat('d',64),'TEST distinct audience must remain available','TEST379-deny-audience')$$,'55000','CATALOG_RELEASE_WINDOW_REVIEW_NOT_ELIGIBLE','a separate audience is not silently cancelled as an orphan duplicate');
select throws_ok($$select public.request_catalog_release_window_closure_v1('d3790000-0000-4000-8000-000000000006',1,repeat('f',64),'TEST publishing lease is not orphaned','TEST379-deny-inflight')$$,'55000','CATALOG_RELEASE_WINDOW_REVIEW_NOT_ELIGIBLE','an in-flight publisher is rejected before governance takes library locks');
select throws_ok($$select public.request_catalog_release_window_closure_v1('d3790000-0000-4000-8000-000000000001',1,repeat('f',64),'TEST wrong source hash','TEST379-deny-hash')$$,'40001','CATALOG_RELEASE_WINDOW_SOURCE_CHANGED','request pins the actual release hash');
insert into windows379 values('request',public.request_catalog_release_window_closure_v1('d3790000-0000-4000-8000-000000000001',1,repeat('a',64),'TEST explicit closure of a noncurrent orphan at decision time','TEST379-request'));
insert into windows379 values('stale-request',public.request_catalog_release_window_closure_v1('d3790000-0000-4000-8000-000000000001',1,repeat('a',64),'TEST second request will become stale after the first decision','TEST379-stale-request'));
select is(jsonb_array_length(public.get_catalog_release_window_context_v1('c3790000-0000-4000-8000-000000000001')->'conflicts'),1,'the bounded context exposes the actual orphan conflict');
select ok(not(public.get_catalog_release_window_context_v1('c3790000-0000-4000-8000-000000000001')#>>'{requests,0,canDecide}')::boolean,'the requester cannot approve their own request');
select throws_ok($$select public.decide_catalog_release_window_closure_v1((select(v->>'request_id')::uuid from windows379 where k='request'),(select v->>'source_hash'from windows379 where k='request'),true,'TEST self approval denied','TEST379-self-approve')$$,'42501','CATALOG_WINDOW_INDEPENDENT_REVIEW_REQUIRED','request author cannot decide their own window closure');
select pg_temp.actor379(2,'aal1');
select throws_ok($$select public.get_catalog_release_window_context_v1()$$,'42501','CENTRAL_MFA_REQUIRED','missing AAL2 is classified independently from an unavailable calendar');
select pg_temp.actor379(3);
select throws_ok($$select public.get_catalog_release_window_context_v1()$$,'42501','CATALOG_SCOPE_DENIED','noncentral role receives no calendar governance context');
select pg_temp.actor379(2);
select throws_ok($$select public.decide_catalog_release_window_closure_v1((select(v->>'request_id')::uuid from windows379 where k='request'),repeat('f',64),true,'TEST stale review hash','TEST379-stale-review')$$,'40001','CATALOG_RELEASE_WINDOW_SOURCE_CHANGED','independent decision pins the exact frozen request source');
insert into windows379 values('closed',public.decide_catalog_release_window_closure_v1((select(v->>'request_id')::uuid from windows379 where k='request'),(select v->>'source_hash'from windows379 where k='request'),true,'TEST independent closure preserving all historical snapshots','TEST379-approve'));
select is((select v->>'outcome'from windows379 where k='closed'),'CATALOG_RELEASE_WINDOW_CLOSED','a second real SQL command actor approves the explicit closure');
select is(public.decide_catalog_release_window_closure_v1((select(v->>'request_id')::uuid from windows379 where k='request'),(select v->>'source_hash'from windows379 where k='request'),true,'TEST independent closure preserving all historical snapshots','TEST379-approve'),(select v from windows379 where k='closed'),'decision retry returns the immutable receipt without extending a window');
select throws_ok($$select public.decide_catalog_release_window_closure_v1((select(v->>'request_id')::uuid from windows379 where k='stale-request'),(select v->>'source_hash'from windows379 where k='stale-request'),true,'TEST cannot approve a changed source','TEST379-deny-stale')$$,'40001','CATALOG_RELEASE_WINDOW_SOURCE_CHANGED','a changed source cannot be approved from a stale second request');
select ok((public.get_catalog_release_window_context_v1('c3790000-0000-4000-8000-000000000001')#>>'{requests,0,sourceChanged}')::boolean,'the pending stale request is marked as changed');
select is(public.decide_catalog_release_window_closure_v1((select(v->>'request_id')::uuid from windows379 where k='stale-request'),(select v->>'source_hash'from windows379 where k='stale-request'),false,'TEST reject obsolete request without touching any window','TEST379-reject-stale')->>'outcome','CATALOG_RELEASE_WINDOW_CLOSURE_REJECTED','an independent reviewer may reject a stale request safely');
select pg_temp.actor379(1);
select is(public.request_catalog_release_window_closure_v1('d3790000-0000-4000-8000-000000000001',1,repeat('a',64),'TEST explicit closure of a noncurrent orphan at decision time','TEST379-request'),(select v from windows379 where k='request'),'request replay still succeeds after its release becomes retired');
insert into windows379 values('schedule',public.schedule_reviewed_catalog_release('d3790000-0000-4000-8000-000000000003',1,repeat('c',64),clock_timestamp(),null,'TEST379-schedule-after-review'));
select is((select v->>'outcome'from windows379 where k='schedule'),'CATALOG_RELEASE_SCHEDULED','the same real scheduler works after independently governed regularization');
reset role;
select is((select to_jsonb(r)-array['status','effective_until','retired_at','row_version']from public.catalog_releases r where id='d3790000-0000-4000-8000-000000000001'),(select v-array['status','effective_until','retired_at','row_version']from windows379 where k='target-before'),'the old snapshot, publication metadata and absent lineage remain unchanged');
select ok((select status='RETIRED'and effective_until=(select(v->>'effective_until')::timestamptz from windows379 where k='closed')and effective_until>=(select requested_at from public.catalog_release_window_requests_v1 where id=(select(v->>'request_id')::uuid from windows379 where k='request'))from public.catalog_releases where id='d3790000-0000-4000-8000-000000000001'),'only future availability ends at the real approval time, never retroactively');
select is((select to_jsonb(r)from public.catalog_releases r where id='d3790000-0000-4000-8000-000000000002'),(select v from windows379 where k='current-before'),'the legitimate current release remains fully available and unchanged');
select is((select current_release_id::text from public.catalog_libraries where id='c3790000-0000-4000-8000-000000000001'),'d3790000-0000-4000-8000-000000000002','reconciliation never changes the current publication pointer');
select is((select status from public.catalog_releases where id='d3790000-0000-4000-8000-000000000004'),'PUBLISHED','the different audience retains its published status');
select is((select count(*)from public.audit_events where action='catalog.release.window_closed'and resource_id='d3790000-0000-4000-8000-000000000001'),1::bigint,'retries produce one immutable closure audit');
select is((select count(*)from public.event_outbox where event_type='CatalogReleaseWindowClosedV1'and aggregate_id=(select v->>'request_id'from windows379 where k='request')),1::bigint,'retries produce one closure outbox effect');
select ok(not has_table_privilege('authenticated','public.catalog_release_window_decisions_v1','insert')and not has_table_privilege('service_role','public.catalog_release_window_requests_v1','insert'),'application and worker cannot fabricate governance records');
select ok(not has_function_privilege('anon','public.request_catalog_release_window_closure_v1(uuid,integer,text,text,text,uuid)','execute')and not has_function_privilege('service_role','public.decide_catalog_release_window_closure_v1(uuid,text,boolean,text,text,uuid)','execute'),'governance mutations are not exposed to anonymous or service principals');
select ok((select pg_get_functiondef('public.complete_catalog_release_publish(uuid,uuid,integer,uuid)'::regprocedure)like'%close_catalog_predecessor_window_v1(v_previous,p_release_id,p_correlation_id)%'),'normal atomic publication invokes the exact predecessor window closer');
select *from finish();rollback;
